using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up the value of a configuration key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'AppName')")] string key)
    {
        var config = AppConfiguration.Current;
        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("List all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", AppConfiguration.Current.Keys.Order());
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfiguration.Current,
            new JsonSerializerOptions { WriteIndented = true });
    }
}

/// <summary>
/// Sample configuration data exposed via MCP tools and resources.
/// Replace with real configuration sources (database, Key Vault, etc.) in production.
/// </summary>
public static class AppConfiguration
{
    public static Dictionary<string, string> Current { get; } = new()
    {
        ["AppName"] = "ConfigMcpServer",
        ["Environment"] = "Development",
        ["MaxRetries"] = "3",
        ["TimeoutSeconds"] = "30",
        ["FeatureFlag_DarkMode"] = "true",
        ["FeatureFlag_BetaAPI"] = "false"
    };
}

